public interface ISpecializedAgent
{
    string Name { get; }
    string CapabilitiesDescription { get; }
    Task<string> ExecuteTaskAsync(string taskDescription, CancellationToken ct = default);
}

public class MultiAgentSupervisor
{
    private readonly IChatClient _routerClient;
    private readonly Dictionary<string, ISpecializedAgent> _agents;

    public MultiAgentSupervisor(IChatClient routerClient, IEnumerable<ISpecializedAgent> agents)
    {
        _routerClient = routerClient;
        _agents = agents.ToDictionary(a => a.Name, StringComparer.OrdinalIgnoreCase);
    }

    public async Task<string> CoordinateAsync(string userGoal, CancellationToken ct = default)
    {
        var agentCatalog = string.Join("\n", _agents.Values.Select(a => $"- {a.Name}: {a.CapabilitiesDescription}"));

        var routingPrompt = 
            $"You are the supervisor of an enterprise agent team.\n" +
            $"Available Agents:\n{agentCatalog}\n\n" +
            $"User Request: '{userGoal}'\n" +
            $"Return JSON with: { 'selectedAgent': 'Name', 'subtaskInstructions': 'refined instructions' }";

        var routingResponse = await _routerClient.CompleteAsync(routingPrompt, cancellationToken: ct);
        var route = JsonSerializer.Deserialize<AgentRouteDecision>(routingResponse.Message.Text!)!;

        if (!_agents.TryGetValue(route.SelectedAgent, out var workerAgent))
        {
            throw new InvalidOperationException($"Agent '{route.SelectedAgent}' not recognized.");
        }

        // Worker executes its specialized domain tools
        var workerOutput = await workerAgent.ExecuteTaskAsync(route.SubtaskInstructions, ct);

        // Supervisor synthesizes final response
        var finalPrompt = $"User Request: {userGoal}\nWorker '{workerAgent.Name}' Output: {workerOutput}\n" +
                          $"Synthesize a clear, verified final response for the user.";

        var finalResponse = await _routerClient.CompleteAsync(finalPrompt, cancellationToken: ct);
        return finalResponse.Message.Text ?? string.Empty;
    }
}

public record AgentRouteDecision(string SelectedAgent, string SubtaskInstructions);
